CREATE TYPE "Industry" AS ENUM ('EDTECH','FINTECH','ECOMMERCE','ENTERTAINMENT','HEALTHCARE','TECHNOLOGY_SAAS','TRAVEL','TELECOMMUNICATIONS','CONSUMER_GOODS_FASHION','GOVERNMENT_PUBLIC_SERVICES');
CREATE TYPE "Severity" AS ENUM ('CRITICAL','HIGH','MODERATE','LOW');
CREATE TYPE "FindingStatus" AS ENUM ('NEW','INVESTIGATING','RESOLVED','FALSE_POSITIVE');
CREATE TABLE "Organisation" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Organisation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "User" ("id" TEXT NOT NULL,"organisationId" TEXT NOT NULL,"email" TEXT NOT NULL,"role" TEXT NOT NULL DEFAULT 'analyst',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Brand" ("id" TEXT NOT NULL,"organisationId" TEXT NOT NULL,"name" TEXT NOT NULL,"aliases" JSONB NOT NULL,"description" TEXT,"logoUrl" TEXT,"industry" "Industry" NOT NULL,"subcategory" TEXT,"websiteUrl" TEXT,"domains" JSONB NOT NULL,"socialProfiles" JSONB NOT NULL,"keywords" JSONB NOT NULL,"impersonationIndicators" JSONB NOT NULL,"mobileApplications" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Brand_pkey" PRIMARY KEY ("id"));
CREATE TABLE "OfficialAsset" ("id" TEXT NOT NULL,"brandId" TEXT NOT NULL,"type" TEXT NOT NULL,"url" TEXT NOT NULL,"label" TEXT,"verified" BOOLEAN NOT NULL DEFAULT false,CONSTRAINT "OfficialAsset_pkey" PRIMARY KEY ("id"));
CREATE TABLE "MonitoringConfiguration" ("id" TEXT NOT NULL,"brandId" TEXT NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT true,"modules" JSONB NOT NULL,"rules" JSONB NOT NULL,"frequency" TEXT NOT NULL DEFAULT 'daily',CONSTRAINT "MonitoringConfiguration_pkey" PRIMARY KEY ("id"));
CREATE TABLE "MonitoringJob" ("id" TEXT NOT NULL,"brandId" TEXT NOT NULL,"startedAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3),"status" TEXT NOT NULL DEFAULT 'queued',CONSTRAINT "MonitoringJob_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Finding" ("id" TEXT NOT NULL,"organisationId" TEXT NOT NULL,"brandId" TEXT NOT NULL,"category" TEXT NOT NULL,"source" TEXT NOT NULL,"affectedEntity" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"sourceUrl" TEXT,"evidence" JSONB NOT NULL,"detectionIndicators" JSONB NOT NULL,"riskScore" INTEGER NOT NULL,"severity" "Severity" NOT NULL,"confidence" INTEGER NOT NULL,"status" "FindingStatus" NOT NULL DEFAULT 'NEW',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Finding_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Evidence" ("id" TEXT NOT NULL,"findingId" TEXT NOT NULL,"kind" TEXT NOT NULL,"value" TEXT NOT NULL,"capturedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Evidence_pkey" PRIMARY KEY ("id"));
CREATE TABLE "RiskAssessment" ("id" TEXT NOT NULL,"findingId" TEXT NOT NULL,"score" INTEGER NOT NULL,"rationale" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "RiskAssessment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Investigation" ("id" TEXT NOT NULL,"findingId" TEXT NOT NULL,"assigneeId" TEXT,"status" TEXT NOT NULL DEFAULT 'open',CONSTRAINT "Investigation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "InvestigationNote" ("id" TEXT NOT NULL,"investigationId" TEXT NOT NULL,"authorId" TEXT NOT NULL,"body" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "InvestigationNote_pkey" PRIMARY KEY ("id"));
CREATE TABLE "StatusHistory" ("id" TEXT NOT NULL,"findingId" TEXT NOT NULL,"status" TEXT NOT NULL,"changedBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "StatusHistory_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ResponseAction" ("id" TEXT NOT NULL,"findingId" TEXT NOT NULL,"action" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'pending',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ResponseAction_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AuditEvent" ("id" TEXT NOT NULL,"organisationId" TEXT NOT NULL,"action" TEXT NOT NULL,"entityType" TEXT NOT NULL,"entityId" TEXT,"metadata" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AuditEvent_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "MonitoringConfiguration_brandId_key" ON "MonitoringConfiguration"("brandId");
CREATE UNIQUE INDEX "RiskAssessment_findingId_key" ON "RiskAssessment"("findingId");
CREATE INDEX "Brand_organisationId_idx" ON "Brand"("organisationId");
ALTER TABLE "User" ADD CONSTRAINT "User_organisationId_fkey" FOREIGN KEY ("organisationId") REFERENCES "Organisation"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Brand" ADD CONSTRAINT "Brand_organisationId_fkey" FOREIGN KEY ("organisationId") REFERENCES "Organisation"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "OfficialAsset" ADD CONSTRAINT "OfficialAsset_brandId_fkey" FOREIGN KEY ("brandId") REFERENCES "Brand"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "MonitoringConfiguration" ADD CONSTRAINT "MonitoringConfiguration_brandId_fkey" FOREIGN KEY ("brandId") REFERENCES "Brand"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Finding" ADD CONSTRAINT "Finding_brandId_fkey" FOREIGN KEY ("brandId") REFERENCES "Brand"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Evidence" ADD CONSTRAINT "Evidence_findingId_fkey" FOREIGN KEY ("findingId") REFERENCES "Finding"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "RiskAssessment" ADD CONSTRAINT "RiskAssessment_findingId_fkey" FOREIGN KEY ("findingId") REFERENCES "Finding"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Investigation" ADD CONSTRAINT "Investigation_findingId_fkey" FOREIGN KEY ("findingId") REFERENCES "Finding"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "InvestigationNote" ADD CONSTRAINT "InvestigationNote_investigationId_fkey" FOREIGN KEY ("investigationId") REFERENCES "Investigation"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
